// Middleware for handling JWT authentication
import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

export const authenticateJWT = (req: Request, res: Response, next: NextFunction) => {
  const token = req.header('Authorization')?.split(' ')[1];
  if (token) {
    jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
      if (err) {
        return res.sendStatus(403);
      }
      req.user = user;
      next();
    });
  } else {
    res.sendStatus(401);
  }
};
```

This middleware handles JWT authentication by:
1. Extracting the token from the Authorization header
2. Verifying it using the JWT_SECRET environment variable
3. Attaching the decoded user to the request object if valid
4. Returning 403 for invalid tokens or 401 if no token is provided
